(1375077, 173135, 31230, '<td valign="top">Wow, now that''s what I call capturing a moment.</td>', 'Wow, now that''s what I call capturing a moment.', '2005-05-10 09:59:17.000000', NULL, 1),
(1375078, 175664, 31230, '<td valign="top">Wonderful I really get the feeling that she is the odd man out.  Nice DOF</td>', 'Wonderful I really get the feeling that she is the odd man out.  Nice DOF', '2005-05-10 10:00:00.000000', NULL, 1),
(1375080, 174736, 31230, '<td valign="top">Love the feel of this shot.  Old but not forgotten</td>', 'Love the feel of this shot.  Old but not forgotten', '2005-05-10 10:00:36.000000', NULL, 1),
(1375082, 175539, 31230, '<td valign="top">Nice sillohuette</td>', 'Nice sillohuette', '2005-05-10 10:01:09.000000', NULL, 1),
(1375099, 175701, 30049, '<td valign="top">This would have been perfect with a child peeking in the window!</td>', 'This would have been perfect with a child peeking in the window!', '2005-05-10 10:13:05.000000', NULL, 1),
(1375144, 175478, 8522, '<td valign="top">Although technically you must be on the outside looking in otherwise you''d be eaten, the photo doesn''t give me a feeling of this quality and doesn''t meet the challenge for me.</td>', 'Although technically you must be on the outside looking in otherwise you''d be eaten, the photo doesn''t give me a feeling of this quality and doesn''t meet the challenge for me.', '2005-05-10 10:42:39.000000', NULL, 1),
(1375147, 175601, 8522, '<td valign="top">Centered eyes usually make for an unimaginative composition. Shallw dof not effective here. I''d hate to have cat hair all over my guitar though!</td>', 'Centered eyes usually make for an unimaginative composition. Shallw dof not effective here. I''d hate to have cat hair all over my guitar though!', '2005-05-10 10:43:37.000000', NULL, 1),
(1375148, 175777, 8522, '<td valign="top">Green looks very sickly, and saturation seems very dull in general. Quality of light is a tad harsh. Composition seems unimaginative.</td>', 'Green looks very sickly, and saturation seems very dull in general. Quality of light is a tad harsh. Composition seems unimaginative.', '2005-05-10 10:44:20.000000', NULL, 1),
(1375152, 175468, 8522, '<td valign="top">Meets the challenge in a lovely, whimsical way. Shame about the blue outside which distracts from the rest of the composition.</td>', 'Meets the challenge in a lovely, whimsical way. Shame about the blue outside which distracts from the rest of the composition.', '2005-05-10 10:45:12.000000', NULL, 1),
(1375153, 175608, 33725, '<td valign="top">I had to stretch my imagination to come up with an "outside looking in" interpretation.  Too big a stretch.  Otherwise it is an interesting photo.  The blown-out area on her back bothers me.  I like your title.</td>', 'I had to stretch my imagination to come up with an "outside looking in" interpretation.  Too big a stretch.  Otherwise it is an interesting photo.  The blown-out area on her back bothers me.  I like your title.', '2005-05-10 10:46:01.000000', NULL, 1),
(1375154, 173927, 8522, '<td valign="top">Interesting composition, wish the dof was deeper extending to the bike. Some great colours. It''s the roof that really looks good in this shot.</td>', 'Interesting composition, wish the dof was deeper extending to the bike. Some great colours. It''s the roof that really looks good in this shot.', '2005-05-10 10:46:20.000000', NULL, 1),
(1375158, 175101, 8522, '<td valign="top">I really like this shot, but wish it was much sharper. Image is slightly wonky, and colour balance seems a tad yellow.</td>', 'I really like this shot, but wish it was much sharper. Image is slightly wonky, and colour balance seems a tad yellow.', '2005-05-10 10:47:02.000000', NULL, 1),
(1375159, 173576, 33725, '<td valign="top">I like the nested view concept but the tilt and lack of focus bother me.  This is a fascinating looking temple.</td>', 'I like the nested view concept but the tilt and lack of focus bother me.  This is a fascinating looking temple.', '2005-05-10 10:47:43.000000', NULL, 1),
(1375161, 175371, 8522, '<td valign="top">Not quite enough to keep interest, and the glare is distracting on the left of the frame. Perhaps narrower dof could have isolated your point of focus more.</td>', 'Not quite enough to keep interest, and the glare is distracting on the left of the frame. Perhaps narrower dof could have isolated your point of focus more.', '2005-05-10 10:47:49.000000', NULL, 1),
(1375164, 175429, 8522, '<td valign="top">The diagonal line is a good compositional element, although centered eyes show a lack of composition imagination. Rule of thirds?</td>', 'The diagonal line is a good compositional element, although centered eyes show a lack of composition imagination. Rule of thirds?', '2005-05-10 10:48:43.000000', NULL, 1),
(1375166, 175525, 8522, '<td valign="top">Slightly overexposed, and the pose looks a little awkward. Nice composition and textures though.</td>', 'Slightly overexposed, and the pose looks a little awkward. Nice composition and textures though.', '2005-05-10 10:50:05.000000', NULL, 1),
(1375170, 174093, 33725, '<td valign="top">I don''t see how this relates to the challenge.  It is  a very emotive capture, however.  The contrast between the too dark foreground and the too light background weakens this image for me.</td>', 'I don''t see how this relates to the challenge.  It is  a very emotive capture, however.  The contrast between the too dark foreground and the too light background weakens this image for me.', '2005-05-10 10:50:35.000000', NULL, 1),
(1375172, 174666, 33725, '<td valign="top">Nice snapshot; but how does it relate to this challenge?</td>', 'Nice snapshot; but how does it relate to this challenge?', '2005-05-10 10:51:46.000000', NULL, 1),
(1375174, 174432, 8522, '<td valign="top">Lovely idea, but the composition is a bit too cluttered... ideally the figures should have a light background without detail just behind them. I realise you have no control over these things here, but I would have just not taken the shot and looked out for it in the future with a different shop.</td>', 'Lovely idea, but the composition is a bit too cluttered... ideally the figures should have a light background without detail just behind them. I realise you have no control over these things here, but I would have just not taken the shot and looked out for it in the future with a different shop.', '2005-05-10 10:52:42.000000', NULL, 1),
(1375175, 175259, 33725, '<td valign="top">I like the concept; I like the reflections on the ball, and I like the way the ball tells me how to score it: 8.</td>', 'I like the concept; I like the reflections on the ball, and I like the way the ball tells me how to score it: 8.', '2005-05-10 10:53:18.000000', NULL, 1),
(1375179, 175731, 37566, '<td valign="top">Never seen a more beautiful Brittany</td>', 'Never seen a more beautiful Brittany', '2005-05-10 10:55:22.000000', NULL, 1),
(1375182, 175210, 8522, '<td valign="top">Snapshot with an unimaginative composition and an awkward expression. Good idea to use fill in flash, but the helmet has resulted in shadows being cast on the face. I would have experimented with unusual angles, perhaps from the side cropping in tightly into the eyes. This would have given more of an atmosphere of resolve and determination rather than a sheepish smile which is not really in keeping with the outfit.</td>', 'Snapshot with an unimaginative composition and an awkward expression. Good idea to use fill in flash, but the helmet has resulted in shadows being cast on the face. I would have experimented with unusual angles, perhaps from the side cropping in tightly into the eyes. This would have given more of an atmosphere of resolve and determination rather than a sheepish smile which is not really in keeping with the outfit.', '2005-05-10 10:55:46.000000', NULL, 1),
(1375183, 174177, 5354, '<td valign="top">Lose the date stamp, and needs more dof</td>', 'Lose the date stamp, and needs more dof', '2005-05-10 10:56:03.000000', NULL, 1),
(1375189, 174809, 8522, '<td valign="top">Composition seems unimaginative, and I don''t see why the top of the door on the right was cropped off. Well done for trying a slightly different angle though... ie near the floor. The shot doesn''t really capture me though or make me interested in the scene.</td>', 'Composition seems unimaginative, and I don''t see why the top of the door on the right was cropped off. Well done for trying a slightly different angle though... ie near the floor. The shot doesn''t really capture me though or make me interested in the scene.', '2005-05-10 10:57:08.000000', NULL, 1),
(1375194, 175608, 8522, '<td valign="top">Love the figure about to exit the frame. Wish it wasn''t slightly overexposed though. I really like the guitar''s composition. Figure''s slumped shoulders helps make this shot interesting.</td>', 'Love the figure about to exit the frame. Wish it wasn''t slightly overexposed though. I really like the guitar''s composition. Figure''s slumped shoulders helps make this shot interesting.', '2005-05-10 10:58:42.000000', NULL, 1),
(1375247, 173281, 6814, '<td valign="top">This is a very creative shot, but I almost wish there was more detail in the area around the knothole.  Having said that, I still like this image a lot.  Nice job.</td>', 'This is a very creative shot, but I almost wish there was more detail in the area around the knothole.  Having said that, I still like this image a lot.  Nice job.', '2005-05-10 11:47:47.000000', NULL, 1),
(1375253, 175799, 6814, '<td valign="top">This is a very creative shot, and I especially like all of the detail in the eye.  The colors are especially nice.</td>', 'This is a very creative shot, and I especially like all of the detail in the eye.  The colors are especially nice.', '2005-05-10 11:49:06.000000', NULL, 1),
(1375254, 175733, 6814, '<td valign="top">The biggest issue I have with this shot is that it appears flat and washed out.  I think it would help to bump up the saturation and contrast a little.</td>', 'The biggest issue I have with this shot is that it appears flat and washed out.  I think it would help to bump up the saturation and contrast a little.', '2005-05-10 11:50:12.000000', NULL, 1),
(1375258, 175314, 6814, '<td valign="top">Very nice nature shot.  I love the detail and color.</td>', 'Very nice nature shot.  I love the detail and color.', '2005-05-10 11:50:59.000000', NULL, 1),
(1375296, 175600, 35720, '<td valign="top">Wonderful shot, great composition and the waterdrops really add to it.</td>', 'Wonderful shot, great composition and the waterdrops really add to it.', '2005-05-10 12:13:23.000000', NULL, 1),
(1375297, 175525, 35720, '<td valign="top">Great shot and meets the challenge very well. I like it a lot.</td>', 'Great shot and meets the challenge very well. I like it a lot.', '2005-05-10 12:14:21.000000', NULL, 1),
(1375303, 175605, 35720, '<td valign="top">I think you have forgot one "i" in the name of the photo. Good shot!</td>', 'I think you have forgot one "i" in the name of the photo. Good shot!', '2005-05-10 12:16:37.000000', NULL, 1),
(1375309, 175490, 35720, '<td valign="top">Very good shot, I like it very much. 8</td>', 'Very good shot, I like it very much. 8', '2005-05-10 12:17:40.000000', NULL, 1),
(1375311, 174690, 35720, '<td valign="top">Well seen and observed. I esp like the reflection and the atmosphere you have captured. 8</td>', 'Well seen and observed. I esp like the reflection and the atmosphere you have captured. 8', '2005-05-10 12:19:12.000000', NULL, 1),
(1375316, 175666, 35720, '<td valign="top">Wonderful shot, very atmospheric and mystic. The fence on the left hand side distracts me a bit, but a great shot though. 8</td>', 'Wonderful shot, very atmospheric and mystic. The fence on the left hand side distracts me a bit, but a great shot though. 8', '2005-05-10 12:21:03.000000', NULL, 1),
(1375318, 175702, 35720, '<td valign="top">Good shot. I like the lighting and the star from the candle light.</td>', 'Good shot. I like the lighting and the star from the candle light.', '2005-05-10 12:22:26.000000', NULL, 1),
(1375319, 175661, 14614, '<td valign="top">like the processing  here- gives it an "old time" feel</td>', 'like the processing  here- gives it an "old time" feel', '2005-05-10 12:22:28.000000', NULL, 1),
(1375381, 173135, 6668, '<td valign="top">Love the capture! Well done!!</td>', 'Love the capture! Well done!!', '2005-05-10 12:52:28.000000', NULL, 1),
(1375488, 174603, 6130, '<td valign="top">Lovely photo and title.</td>', 'Lovely photo and title.', '2005-05-10 13:49:41.000000', NULL, 1),
(1375507, 175475, 37371, '<td valign="top">Love it!!</td>', 'Love it!!', '2005-05-10 13:57:38.000000', NULL, 1);
