(1375563, 174736, 31443, '<td valign="top">Interesting subject...</td>', 'Interesting subject...', '2005-05-10 14:22:39.000000', NULL, 1),
(1375578, 175126, 6814, '<td valign="top">I''m not sure how this fits with the theme, but it''s a beautiful photograph.  There is a great amount of detail, and the colors, though muted, are pleasing.</td>', 'I''m not sure how this fits with the theme, but it''s a beautiful photograph.  There is a great amount of detail, and the colors, though muted, are pleasing.', '2005-05-10 14:28:22.000000', NULL, 1),
(1375581, 173617, 6814, '<td valign="top">This is a wonderful image that makes terrific use of available light.  It reminds me of one of Edward Hopper''s paintings.  Very nice job!</td>', 'This is a wonderful image that makes terrific use of available light.  It reminds me of one of Edward Hopper''s paintings.  Very nice job!', '2005-05-10 14:30:28.000000', NULL, 1),
(1375585, 175525, 31443, '<td valign="top">Good choice for a door and the model looking down, makes this composition more natural, nice light...</td>', 'Good choice for a door and the model looking down, makes this composition more natural, nice light...', '2005-05-10 14:31:42.000000', NULL, 1),
(1375588, 175558, 31443, '<td valign="top">Crystal clear and well lit, like it lots...</td>', 'Crystal clear and well lit, like it lots...', '2005-05-10 14:32:47.000000', NULL, 1),
(1375589, 175552, 6814, '<td valign="top">Fantastic detail! The colors and sharpness of focus really make this shot.</td>', 'Fantastic detail! The colors and sharpness of focus really make this shot.', '2005-05-10 14:33:00.000000', NULL, 1),
(1375592, 175665, 6814, '<td valign="top">I like the monochromatic quality of this image a lot.  Great composition.</td>', 'I like the monochromatic quality of this image a lot.  Great composition.', '2005-05-10 14:34:13.000000', NULL, 1),
(1375594, 175598, 31443, '<td valign="top">Mysterious feeling about this building, wonder if I''ve been there? Nice balance...</td>', 'Mysterious feeling about this building, wonder if I''ve been there? Nice balance...', '2005-05-10 14:34:51.000000', NULL, 1),
(1375598, 175666, 6814, '<td valign="top">This image is very surreal with the transition from grey scale to color.  Nice job.</td>', 'This image is very surreal with the transition from grey scale to color.  Nice job.', '2005-05-10 14:35:30.000000', NULL, 1),
(1375603, 175600, 6814, '<td valign="top">Great use of color to add a higher level of interest.  I amount of detail is also very pleasing.</td>', 'Great use of color to add a higher level of interest.  I amount of detail is also very pleasing.', '2005-05-10 14:37:38.000000', NULL, 1),
(1375608, 173233, 6814, '<td valign="top">Very nice capture.  I would like to see the saturation selectively bumped up on the women''s dresses.</td>', 'Very nice capture.  I would like to see the saturation selectively bumped up on the women''s dresses.', '2005-05-10 14:39:37.000000', NULL, 1),
(1375609, 175803, 31443, '<td valign="top">Pity about the glare beside the man sitting, interesting angle..</td>', 'Pity about the glare beside the man sitting, interesting angle..', '2005-05-10 14:40:09.000000', NULL, 1),
(1375611, 175490, 6814, '<td valign="top">The deep shadow on the girl''s face is a little distracting.  Otherwise, this is a great capture.</td>', 'The deep shadow on the girl''s face is a little distracting.  Otherwise, this is a great capture.', '2005-05-10 14:40:40.000000', NULL, 1),
(1375612, 175801, 6814, '<td valign="top">I like the multiple colors in this capture.  The sharpness of the image also keeps the viewer''s interest.</td>', 'I like the multiple colors in this capture.  The sharpness of the image also keeps the viewer''s interest.', '2005-05-10 14:42:21.000000', NULL, 1),
(1375615, 175635, 6814, '<td valign="top">There''s lot''s of interest in this image because of the textures, color and contrast.  Well captured!</td>', 'There''s lot''s of interest in this image because of the textures, color and contrast.  Well captured!', '2005-05-10 14:43:21.000000', NULL, 1),
(1375616, 175568, 6814, '<td valign="top">Very humorous.  Nice job.</td>', 'Very humorous.  Nice job.', '2005-05-10 14:44:01.000000', NULL, 1),
(1375619, 175444, 6814, '<td valign="top">The colors are brilliant, but the fuzzy focus is very distracting.</td>', 'The colors are brilliant, but the fuzzy focus is very distracting.', '2005-05-10 14:45:06.000000', NULL, 1),
(1375621, 175408, 6814, '<td valign="top">Excellent detail and control of lighting.  Very nice image.</td>', 'Excellent detail and control of lighting.  Very nice image.', '2005-05-10 14:45:48.000000', NULL, 1),
(1375623, 174592, 6814, '<td valign="top">I love the detail in the wood captured here.  Very nicely done.</td>', 'I love the detail in the wood captured here.  Very nicely done.', '2005-05-10 14:46:25.000000', NULL, 1),
(1375630, 175475, 31443, '<td valign="top">Nice and yummie looking, could have been sharper though, with this quality photography i.e. probably a great camera..</td>', 'Nice and yummie looking, could have been sharper though, with this quality photography i.e. probably a great camera..', '2005-05-10 14:47:19.000000', NULL, 1),
(1375632, 174834, 6814, '<td valign="top">Very nicely composed.  The theme is similar to my entry in this challenge.  Yours is better!</td>', 'Very nicely composed.  The theme is similar to my entry in this challenge.  Yours is better!', '2005-05-10 14:48:01.000000', NULL, 1),
(1375634, 175760, 31443, '<td valign="top">Nice and warm colors, very inviting..</td>', 'Nice and warm colors, very inviting..', '2005-05-10 14:48:27.000000', NULL, 1),
(1375639, 174432, 6814, '<td valign="top">In most cases, a good photograph tells a story without needing words to explain.  Excellent capture!</td>', 'In most cases, a good photograph tells a story without needing words to explain.  Excellent capture!', '2005-05-10 14:49:06.000000', NULL, 1),
(1375640, 175797, 6814, '<td valign="top">Capturing your own reflection in the glass makes this image.  I''m especially drawn by the warm colors.  Nice job.</td>', 'Capturing your own reflection in the glass makes this image.  I''m especially drawn by the warm colors.  Nice job.', '2005-05-10 14:50:16.000000', NULL, 1),
(1375644, 173733, 31443, '<td valign="top">So this is what mailboxes look like in the US! Always wondered, nice idea for the tilt. pro looking stuff..</td>', 'So this is what mailboxes look like in the US! Always wondered, nice idea for the tilt. pro looking stuff..', '2005-05-10 14:51:13.000000', NULL, 1),
(1375645, 175702, 6814, '<td valign="top">Beautiful, warm scene that has been captured very nicely.  Well seen!</td>', 'Beautiful, warm scene that has been captured very nicely.  Well seen!', '2005-05-10 14:51:22.000000', NULL, 1),
(1375650, 175251, 6814, '<td valign="top">In this case, the people in the shot are a distraction.</td>', 'In this case, the people in the shot are a distraction.', '2005-05-10 14:51:55.000000', NULL, 1),
(1375654, 175664, 6814, '<td valign="top">The choice to do this in black and white helps to create the mood of this image.  Very nice job!</td>', 'The choice to do this in black and white helps to create the mood of this image.  Very nice job!', '2005-05-10 14:53:52.000000', NULL, 1),
(1375660, 173135, 6814, '<td valign="top">Whoooo!!!  Somebody''s angry.  Nice shot.</td>', 'Whoooo!!!  Somebody''s angry.  Nice shot.', '2005-05-10 14:55:02.000000', NULL, 1),
(1375663, 175627, 6814, '<td valign="top">Excellent detail and lighting.  Nice job.</td>', 'Excellent detail and lighting.  Nice job.', '2005-05-10 14:56:04.000000', NULL, 1),
(1375672, 175495, 6814, '<td valign="top">For this to work, the focus would have to be absolutely sharp.</td>', 'For this to work, the focus would have to be absolutely sharp.', '2005-05-10 14:59:08.000000', NULL, 1),
(1375938, 175537, 24065, '<td valign="top">I''ve looked at this photo for several minutes trying to decide on a score.  The photo of the dog is excellent -- he''s perfectly in focus from his shiny black nose to the hair on his head (I really like the shiny nose, too!), there''s great light in his eyes, and the photo certainly meets the challenge.  The angle of the dog house is really distracting to me, tho.  I think I would have straightened the lines of the dog house to be parallel to the photo edges and left his head a little tilted rather than straightening his head and having the lines tilted.  I would also crop it to just above the hair on his head so the opening would be showing in the top right.  If possible, it would also improve the composition, IMO, if there had been a little more white space on the left, but that''s a minor point.  This photo shows that you have skill as a photographer, it just needs a little work on the composition :)  Hope this will be helpful in your future entries.</td>', 'I''ve looked at this photo for several minutes trying to decide on a score.  The photo of the dog is excellent -- he''s perfectly in focus from his shiny black nose to the hair on his head (I really like the shiny nose, too!), there''s great light in his eyes, and the photo certainly meets the challenge.  The angle of the dog house is really distracting to me, tho.  I think I would have straightened the lines of the dog house to be parallel to the photo edges and left his head a little tilted rather than straightening his head and having the lines tilted.  I would also crop it to just above the hair on his head so the opening would be showing in the top right.  If possible, it would also improve the composition, IMO, if there had been a little more white space on the left, but that''s a minor point.  This photo shows that you have skill as a photographer, it just needs a little work on the composition :)  Hope this will be helpful in your future entries.', '2005-05-10 16:49:41.000000', NULL, 1),
(1375940, 175444, 24065, '<td valign="top">The colors are beautiful!  And I love a shallow DOF.  I haven''t seen them do well on DPC, tho.  Wonderful composition.  8</td>', 'The colors are beautiful!  And I love a shallow DOF.  I haven''t seen them do well on DPC, tho.  Wonderful composition.  8', '2005-05-10 16:50:53.000000', NULL, 1),
(1375944, 175385, 24065, '<td valign="top">I love it!  9</td>', 'I love it!  9', '2005-05-10 16:52:26.000000', NULL, 1),
(1375948, 175259, 24065, '<td valign="top">Fantastic!!  9</td>', 'Fantastic!!  9', '2005-05-10 16:54:20.000000', NULL, 1),
(1375958, 175558, 24065, '<td valign="top">Wow!  I don''t see any room for improvement in this one!  10</td>', 'Wow!  I don''t see any room for improvement in this one!  10', '2005-05-10 16:56:27.000000', NULL, 1),
(1375959, 175525, 24065, '<td valign="top">Beautiful!  9</td>', 'Beautiful!  9', '2005-05-10 16:57:01.000000', NULL, 1),
