(1383672, 175806, 6814, '<td valign="top">Very nice, moody, image.  I like the way you''ve used the natural light, and your DOF is nicely controlled.</td>', 'Very nice, moody, image.  I like the way you''ve used the natural light, and your DOF is nicely controlled.', '2005-05-13 12:53:28.000000', NULL, 1),
(1383678, 175614, 6814, '<td valign="top">Excellent use of natural lighting.  This image shows a lot of imagination and creativity.  Well done!</td>', 'Excellent use of natural lighting.  This image shows a lot of imagination and creativity.  Well done!', '2005-05-13 12:54:29.000000', NULL, 1),
(1383680, 175429, 6814, '<td valign="top">Very cute image.  I wonder if you used a polarizing filter?  There''s a little bit of haze in front of her face that I find distracting.</td>', 'Very cute image.  I wonder if you used a polarizing filter?  There''s a little bit of haze in front of her face that I find distracting.', '2005-05-13 12:55:47.000000', NULL, 1),
(1383687, 174177, 6814, '<td valign="top">Get rid of the date stamp.  It''s very distracting.  I don''t know why anyone would turn that feature on in the camera, or why it''s even a feature to begin with.</td>', 'Get rid of the date stamp.  It''s very distracting.  I don''t know why anyone would turn that feature on in the camera, or why it''s even a feature to begin with.', '2005-05-13 12:57:58.000000', NULL, 1),
(1383692, 174603, 6814, '<td valign="top">Gorgeous detail with fantastic lighting.  Beautiful photograph that shows creativity in how the shot was composed.</td>', 'Gorgeous detail with fantastic lighting.  Beautiful photograph that shows creativity in how the shot was composed.', '2005-05-13 12:59:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1383696, 174093, 6814, '<td valign="top">I would like this a lot better if the detail in the shadows was better.  Still a nice shot that tells a story.</td>', 'I would like this a lot better if the detail in the shadows was better.  Still a nice shot that tells a story.', '2005-05-13 13:01:17.000000', NULL, 1),
(1383699, 175109, 6814, '<td valign="top">Great job capturing the reflection of the barn.  I like everything about this shot - the colors, the sharpness, the imperfections of the glass with dust and paint on the panes...very nice photo.</td>', 'Great job capturing the reflection of the barn.  I like everything about this shot - the colors, the sharpness, the imperfections of the glass with dust and paint on the panes...very nice photo.', '2005-05-13 13:03:01.000000', NULL, 1),
(1383701, 173576, 6814, '<td valign="top">This is so out of focus it''s difficult to look at.</td>', 'This is so out of focus it''s difficult to look at.', '2005-05-13 13:04:03.000000', NULL, 1),
(1383703, 173927, 6814, '<td valign="top">If this could have been framed better so that the bottom of the tires weren''t cropped it would improve the shot a lot.  Still, a good effort.</td>', 'If this could have been framed better so that the bottom of the tires weren''t cropped it would improve the shot a lot.  Still, a good effort.', '2005-05-13 13:05:48.000000', NULL, 1),
(1383706, 174944, 6814, '<td valign="top">Your reflection in the glass distracts rather than adds to the interest.</td>', 'Your reflection in the glass distracts rather than adds to the interest.', '2005-05-13 13:06:47.000000', NULL, 1),
(1383708, 174084, 6814, '<td valign="top">This one put a smile on my face.  Nice capture.</td>', 'This one put a smile on my face.  Nice capture.', '2005-05-13 13:07:20.000000', NULL, 1),
(1383713, 175808, 6814, '<td valign="top">Very creative image.  I like the addition of the color element.</td>', 'Very creative image.  I like the addition of the color element.', '2005-05-13 13:09:05.000000', NULL, 1),
(1383715, 175283, 6814, '<td valign="top">This is more accurately "inside looking out".  I like the mood of this image a lot.  She''s very cute with a winning smile.  Very nice job.</td>', 'This is more accurately "inside looking out".  I like the mood of this image a lot.  She''s very cute with a winning smile.  Very nice job.', '2005-05-13 13:10:12.000000', NULL, 1),
(1383718, 175525, 6814, '<td valign="top">I love the use of the natural light and the way you''ve framed the shot.  The skin tones are very natural and pleasing.</td>', 'I love the use of the natural light and the way you''ve framed the shot.  The skin tones are very natural and pleasing.', '2005-05-13 13:11:15.000000', NULL, 1),
(1383725, 175760, 6814, '<td valign="top">The colors and detail are excellent.  Very nice capture.</td>', 'The colors and detail are excellent.  Very nice capture.', '2005-05-13 13:13:40.000000', NULL, 1),
(1383735, 175615, 6814, '<td valign="top">There''s nothing here but out of focus blurring.</td>', 'There''s nothing here but out of focus blurring.', '2005-05-13 13:17:07.000000', NULL, 1),
(1383736, 175731, 6814, '<td valign="top">Beautiful color and detail.  Nice job.</td>', 'Beautiful color and detail.  Nice job.', '2005-05-13 13:17:47.000000', NULL, 1),
