(1386391, 175537, 35895, '<td valign="top">awesome composition!</td>', 'awesome composition!', '2005-05-15 00:44:23.000000', NULL, 1),
(1386435, 175793, 22748, '<td valign="top">WOW! That''s incredible. Can''t wait to see how you did this. Are they posters? Rear-projection with an LCD projector? It looks too luminous to simply be prints attached to the wall, so I''m betting there is some kind of projection going on.<br/> <br/>Truly brilliant.</td>', 'WOW! That''s incredible. Can''t wait to see how you did this. Are they posters? Rear-projection with an LCD projector? It looks too luminous to simply be prints attached to the wall, so I''m betting there is some kind of projection going on. Truly brilliant.', '2005-05-15 01:22:46.000000', NULL, 1),
(1386497, 175517, 22748, '<td valign="top">Wow! How wierd is that?! I really can''t figure out what it is. Bizzarre and interesting.</td>', 'Wow! How wierd is that?! I really can''t figure out what it is. Bizzarre and interesting.', '2005-05-15 03:06:00.000000', NULL, 1),
(1386507, 174177, 30490, '<td valign="top">Pretty flower, but too blurry for my taste.  I think your DOF is not clear.</td>', 'Pretty flower, but too blurry for my taste.  I think your DOF is not clear.', '2005-05-15 03:26:04.000000', NULL, 1),
(1386508, 173576, 30490, '<td valign="top">Great idea and composition, but too out of focus to really have the impact that you were looking for from the viewer.</td>', 'Great idea and composition, but too out of focus to really have the impact that you were looking for from the viewer.', '2005-05-15 03:26:48.000000', NULL, 1),
(1386509, 175495, 30490, '<td valign="top">Interesting idea, the title does draw the viewer into the image, but it is too hazy/noisy to work well in my opinion</td>', 'Interesting idea, the title does draw the viewer into the image, but it is too hazy/noisy to work well in my opinion', '2005-05-15 03:27:49.000000', NULL, 1),
(1386511, 174662, 30490, '<td valign="top">While this meets the challenge, the lack of color (exept the remander of the liquid in the glass) makes this image not as interesting as it could be if there was a more interesting or colorful background.</td>', 'While this meets the challenge, the lack of color (exept the remander of the liquid in the glass) makes this image not as interesting as it could be if there was a more interesting or colorful background.', '2005-05-15 03:29:28.000000', NULL, 1),
(1386519, 175115, 22748, '<td valign="top">Wow, nice illusion. Can''t wait to hear how you did it. Is it a cutout of a photo? because it looks like the light is coming from the right side of the image on the model, and from the left side of the image for the box, based on shadows. Nicely done though.</td>', 'Wow, nice illusion. Can''t wait to hear how you did it. Is it a cutout of a photo? because it looks like the light is coming from the right side of the image on the model, and from the left side of the image for the box, based on shadows. Nicely done though.', '2005-05-15 03:50:53.000000', NULL, 1),
(1386520, 175303, 22748, '<td valign="top">Great picture! Emotional, original, creative. I really like this one, I hope it wins.</td>', 'Great picture! Emotional, original, creative. I really like this one, I hope it wins.', '2005-05-15 03:52:11.000000', NULL, 1),
(1386523, 175751, 22748, '<td valign="top">Wow, what a weird sculpture. Intersting!</td>', 'Wow, what a weird sculpture. Intersting!', '2005-05-15 03:56:23.000000', NULL, 1),
(1386546, 175259, 6804, '<td valign="top">This is my favorite of the challenge!  It''s so simple, and so clean.  I like centered shots that work in an artistic way.  They are quite difficult to do well.   Great reflection.  10</td>', 'This is my favorite of the challenge!  It''s so simple, and so clean.  I like centered shots that work in an artistic way.  They are quite difficult to do well.   Great reflection.  10', '2005-05-15 05:28:27.000000', NULL, 1),
(1386599, 174914, 31443, '<td valign="top">Like the angle of this image but it would be difficult to look inside any of these windows...</td>', 'Like the angle of this image but it would be difficult to look inside any of these windows...', '2005-05-15 07:30:44.000000', NULL, 1),
(1386612, 175664, 7531, '<td valign="top">I like this, but the color bothers me, take the blue down, add a little more red and play with the curves to add some tonal range.</td>', 'I like this, but the color bothers me, take the blue down, add a little more red and play with the curves to add some tonal range.', '2005-05-15 07:52:13.000000', NULL, 1),
(1386868, 175468, 31443, '<td valign="top">Bird oesn''t look life, scene is nice though..</td>', 'Bird oesn''t look life, scene is nice though..', '2005-05-15 14:48:31.000000', NULL, 1),
(1386869, 175721, 31443, '<td valign="top">A little later in the day with slower shutterspeed...plants look a little overexposed..</td>', 'A little later in the day with slower shutterspeed...plants look a little overexposed..', '2005-05-15 14:50:50.000000', NULL, 1),
(1386886, 175574, 33947, '<td valign="top">Nice sharpness, rich color, great highlights/shadow and contrast. 8</td>', 'Nice sharpness, rich color, great highlights/shadow and contrast. 8', '2005-05-15 15:23:31.000000', NULL, 1),
(1386887, 175176, 30392, '<td valign="top">Fantastic capture of the dancing jellyfishes! I would prefer the image without the person in front, though</td>', 'Fantastic capture of the dancing jellyfishes! I would prefer the image without the person in front, though', '2005-05-15 15:23:35.000000', NULL, 1),
(1386930, 175793, 16241, '<td valign="top">ribbon!</td>', 'ribbon!', '2005-05-15 16:30:16.000000', NULL, 1),
(1386942, 175690, 33947, '<td valign="top">Really sharp and clear egg and pan. Nice lighting and highlights.</td>', 'Really sharp and clear egg and pan. Nice lighting and highlights.', '2005-05-15 16:54:42.000000', NULL, 1),
(1386994, 174084, 17203, '<td valign="top">LOL- hilarious title. Good shot for this challenge. The dog is big enough that you could show even more of the frame for context. 8</td>', 'LOL- hilarious title. Good shot for this challenge. The dog is big enough that you could show even more of the frame for context. 8', '2005-05-15 18:15:10.000000', NULL, 1),
(1387027, 174736, 32341, '<td valign="top">A bit too dark for my liking.  I also think it could have been cropped without losing anything.  There is a lot of black space above the hat.</td>', 'A bit too dark for my liking.  I also think it could have been cropped without losing anything.  There is a lot of black space above the hat.', '2005-05-15 18:56:25.000000', NULL, 1),
(1387033, 175101, 12578, '<td valign="top">Wonderful image, must have a great view at 100%, I reckon theres something mischevous going on in one of those windows... Best shot in the challenge I have seen so far and such a good lot of thought gone into this. Good luck</td>', 'Wonderful image, must have a great view at 100%, I reckon theres something mischevous going on in one of those windows... Best shot in the challenge I have seen so far and such a good lot of thought gone into this. Good luck', '2005-05-15 19:02:51.000000', NULL, 1),
(1387038, 175797, 12578, '<td valign="top">Like the reflection of yourself, personally after looking at this for a moment or two would prefer to see you more in it ( i.e. the mid of you r bdoy as well as your head ) Good take on the topic and great picture...</td>', 'Like the reflection of yourself, personally after looking at this for a moment or two would prefer to see you more in it ( i.e. the mid of you r bdoy as well as your head ) Good take on the topic and great picture...', '2005-05-15 19:05:29.000000', NULL, 1),
(1387074, 175495, 12578, '<td valign="top">tad blurry</td>', 'tad blurry', '2005-05-15 19:25:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1387117, 175371, 1031, '<td valign="top">Nice color, texture, and angle of view.</td>', 'Nice color, texture, and angle of view.', '2005-05-15 19:45:52.000000', NULL, 1),
(1387130, 175666, 35746, '<td valign="top">this is my favorite shot in the challenge....good luck!!!</td>', 'this is my favorite shot in the challenge....good luck!!!', '2005-05-15 19:59:22.000000', NULL, 1),
(1387135, 175644, 1031, '<td valign="top">"On the outside, looking in," sounds like how a hitter might explain taking a called third strike ...  : )<br/> <br/>Nice action capture.</td>', '"On the outside, looking in," sounds like how a hitter might explain taking a called third strike ...  : ) Nice action capture.', '2005-05-15 20:01:12.000000', NULL, 1),
(1387139, 175567, 1031, '<td valign="top">Good idea and execution. I''d have probably had the title make a reference to the myth of Pandora''s Box.</td>', 'Good idea and execution. I''d have probably had the title make a reference to the myth of Pandora''s Box.', '2005-05-15 20:03:42.000000', NULL, 1),
(1387147, 175666, 1031, '<td valign="top">Good choice of a photo to demonstrate the effective use of this technique. Nice parallel lines with the two major trunks. It''s possible that moving slightly to the right would show a bit more of the further trunk.</td>', 'Good choice of a photo to demonstrate the effective use of this technique. Nice parallel lines with the two major trunks. It''s possible that moving slightly to the right would show a bit more of the further trunk.', '2005-05-15 20:11:34.000000', NULL, 1),
(1387161, 175631, 1031, '<td valign="top">Probably has a license at least ... : )<br/> <br/>Although I suspect the translation would probably come out closer to "Where to, Mac?"</td>', 'Probably has a license at least ... : ) Although I suspect the translation would probably come out closer to "Where to, Mac?"', '2005-05-15 20:18:00.000000', NULL, 1),
(1387162, 175259, 1031, '<td valign="top">You had a choice of fifteen balls ... is this some form of subliminal advertising? : )<br/> <br/>Nice control/use of the reflections.</td>', 'You had a choice of fifteen balls ... is this some form of subliminal advertising? : ) Nice control/use of the reflections.', '2005-05-15 20:20:40.000000', NULL, 1),
(1387286, 175662, 22734, '<td valign="top">To think that these creatures can express so much emotion. It is no illusion Dogs like cats and many other life forms can feel and express emotions. Something to ponder upon. Great capture. Coming back to bump this little guy.</td>', 'To think that these creatures can express so much emotion. It is no illusion Dogs like cats and many other life forms can feel and express emotions. Something to ponder upon. Great capture. Coming back to bump this little guy.', '2005-05-15 21:56:24.000000', NULL, 1),
(1387298, 175736, 33817, '<td valign="top">This one gets marks for both execution and its chuckle factor!  Well exposed and perhaps an otherwise ordinary snapshot, the caption coupled with the view and its universal appeal to the Born Loser in all of us raises it well above average.  Great idea!</td>', 'This one gets marks for both execution and its chuckle factor!  Well exposed and perhaps an otherwise ordinary snapshot, the caption coupled with the view and its universal appeal to the Born Loser in all of us raises it well above average.  Great idea!', '2005-05-15 22:05:14.000000', NULL, 1),
(1387305, 175664, 33817, '<td valign="top">Nice subtle use of DOF to keep the other kids very slightly clear while maintaining good focus on the subject.  Here''s hoping the injury that leaves her(?) out of action is soon healed and little more than a memory.  Assuming the toning was meant to be in keeping with the ''mood'' intended, I think you could have given it just a bit more contrast without losing the message.  All in all, well done.</td>', 'Nice subtle use of DOF to keep the other kids very slightly clear while maintaining good focus on the subject.  Here''s hoping the injury that leaves her(?) out of action is soon healed and little more than a memory.  Assuming the toning was meant to be in keeping with the ''mood'' intended, I think you could have given it just a bit more contrast without losing the message.  All in all, well done.', '2005-05-15 22:09:19.000000', NULL, 1),
(1387310, 174888, 33817, '<td valign="top">This is one of those "Huh?" photos that has me running all the possibilities I can imagine through my head to try to sort out the How? before the voting ends and your comments become available.  If this was a double-exposure using some sort of ''barn door'' to cover half the lens at a time, kudos for posing and masking for the shots!  If it was done by another means ... well, I can''t wait to read about them!</td>', 'This is one of those "Huh?" photos that has me running all the possibilities I can imagine through my head to try to sort out the How? before the voting ends and your comments become available.  If this was a double-exposure using some sort of ''barn door'' to cover half the lens at a time, kudos for posing and masking for the shots!  If it was done by another means ... well, I can''t wait to read about them!', '2005-05-15 22:11:54.000000', NULL, 1),
(1387313, 175303, 33817, '<td valign="top">I love this!  Just enough clarity and just enough ambiguity ... would likely have done well in <b>Silhouette II</b> with a bit less detail on the couple.</td>', 'I love this!  Just enough clarity and just enough ambiguity ... would likely have done well in Silhouette II with a bit less detail on the couple.', '2005-05-15 22:14:21.000000', NULL, 1),
(1387318, 175534, 33817, '<td valign="top">This is a good reflection shot but I just don''t get the feeling that I''m <b>looking in</b> ... the reflection reinforces that I''m looking in two directions but they''re AT the building and BEHIND the camera.  Neither seems to be <b>in</b>.</td>', 'This is a good reflection shot but I just don''t get the feeling that I''m looking in ... the reflection reinforces that I''m looking in two directions but they''re AT the building and BEHIND the camera.  Neither seems to be in.', '2005-05-15 22:16:47.000000', NULL, 1),
(1387322, 173576, 33817, '<td valign="top">This clearly meets the challenge description ... but falls short in terms of clearly showing the interior on any level.  It''s a shame -- a wonderful subject that no doubt holds tremendous potential and yet it''s sufficiently lacking in focus to leave me wondering where exactly the plane of focus was?  I don''t mean this to sound harsh -- I really tried to find an area of focus and that kept me from appreciating the details I wish I were seeing . . .</td>', 'This clearly meets the challenge description ... but falls short in terms of clearly showing the interior on any level.  It''s a shame -- a wonderful subject that no doubt holds tremendous potential and yet it''s sufficiently lacking in focus to leave me wondering where exactly the plane of focus was?  I don''t mean this to sound harsh -- I really tried to find an area of focus and that kept me from appreciating the details I wish I were seeing . . .', '2005-05-15 22:20:25.000000', NULL, 1),
(1387325, 175751, 13772, '<td valign="top">Wow! That is one wild statue. Very interesting.</td>', 'Wow! That is one wild statue. Very interesting.', '2005-05-15 22:21:51.000000', NULL, 1),
(1387329, 175662, 33817, '<td valign="top">Good DOF and nice, crisp focus on the forlorn expression ... did you adopt this one?</td>', 'Good DOF and nice, crisp focus on the forlorn expression ... did you adopt this one?', '2005-05-15 22:23:22.000000', NULL, 1),
(1387332, 175793, 33817, '<td valign="top">This is good -- and funny -- but suffers some from a lack of crispness on your heroine (or is she the victim?).  Terrific idea nonetheless -- good luck!</td>', 'This is good -- and funny -- but suffers some from a lack of crispness on your heroine (or is she the victim?).  Terrific idea nonetheless -- good luck!', '2005-05-15 22:25:58.000000', NULL, 1),
(1387334, 175475, 22734, '<td valign="top">Very nice color and lovely presentation.</td>', 'Very nice color and lovely presentation.', '2005-05-15 22:28:03.000000', NULL, 1),
(1387338, 175379, 33817, '<td valign="top">Great idea!  I''d like to see a bit better focus and sharpness on the pretzels though.  Nice effort regardless.</td>', 'Great idea!  I''d like to see a bit better focus and sharpness on the pretzels though.  Nice effort regardless.', '2005-05-15 22:31:14.000000', NULL, 1),
(1387342, 175534, 22734, '<td valign="top">Great capture to tease the viewer.</td>', 'Great capture to tease the viewer.', '2005-05-15 22:31:59.000000', NULL, 1),
(1387347, 175666, 28108, '<td valign="top">Veeerrry cool ! Use of desaturation is way justifiable with great results. I like how the tree blends in with the bagkgorund, it''s almost as if ti was carved in. Very interesting to look at and beautiful. Good luck !</td>', 'Veeerrry cool ! Use of desaturation is way justifiable with great results. I like how the tree blends in with the bagkgorund, it''s almost as if ti was carved in. Very interesting to look at and beautiful. Good luck !', '2005-05-15 22:33:07.000000', NULL, 1),
(1387348, 175539, 22734, '<td valign="top">Hey, this would have a home too in tonights challenge. Very nice.</td>', 'Hey, this would have a home too in tonights challenge. Very nice.', '2005-05-15 22:33:23.000000', NULL, 1),
(1387353, 175501, 33817, '<td valign="top">This is a tough shot to vote for me -- I like the concept and execution but wish the subject were clearer.  Knowing that may be unreasonable to expect considering the secondary ''lens'' in the equation, I''m going with my fondness for your idea.  Good job ... didja let her in?</td>', 'This is a tough shot to vote for me -- I like the concept and execution but wish the subject were clearer.  Knowing that may be unreasonable to expect considering the secondary ''lens'' in the equation, I''m going with my fondness for your idea.  Good job ... didja let her in?', '2005-05-15 22:35:37.000000', NULL, 1),
(1387355, 175379, 30392, '<td valign="top">LOL! not the most beautiful photo, but very original and well executed 8</td>', 'LOL! not the most beautiful photo, but very original and well executed 8', '2005-05-15 22:37:38.000000', NULL, 1),
(1387360, 175795, 33817, '<td valign="top">Secondary voyuerism is an interesting idea -- but at this size, she looks to be watching back and unless she''s calling the police, it pushes the credibility envelope.  I suppose it''s staged -- but consistent staging would make it even better from this perspective.</td>', 'Secondary voyuerism is an interesting idea -- but at this size, she looks to be watching back and unless she''s calling the police, it pushes the credibility envelope.  I suppose it''s staged -- but consistent staging would make it even better from this perspective.', '2005-05-15 22:39:56.000000', NULL, 1),
(1387362, 173281, 33817, '<td valign="top">I really like the clarity of the view through the knothole.  It''s a tough call but I get a sense that it could still convey the idea if the ''view'' were a bit larger -- or if there were something more arresting for the viewer''s attention to explain the suggestion of ''peering'' where one perhaps shouldn''t.</td>', 'I really like the clarity of the view through the knothole.  It''s a tough call but I get a sense that it could still convey the idea if the ''view'' were a bit larger -- or if there were something more arresting for the viewer''s attention to explain the suggestion of ''peering'' where one perhaps shouldn''t.', '2005-05-15 22:42:32.000000', NULL, 1),
(1387364, 175558, 30392, '<td valign="top">Crisp details, good DOF, great reflection, can''t see anything wrong!</td>', 'Crisp details, good DOF, great reflection, can''t see anything wrong!', '2005-05-15 22:42:59.000000', NULL, 1),
(1387368, 174289, 22734, '<td valign="top">This is a very strong image in composition and lighting. Personally, i would have desaturated a bit so as not to have the hue detract from the overall impression. Very good effort. Bumping up.</td>', 'This is a very strong image in composition and lighting. Personally, i would have desaturated a bit so as not to have the hue detract from the overall impression. Very good effort. Bumping up.', '2005-05-15 22:44:38.000000', NULL, 1),
(1387371, 174289, 33947, '<td valign="top">I like your take on the challenge very much, and the clarity and sharpness and lighting are incredible. Very nice job.</td>', 'I like your take on the challenge very much, and the clarity and sharpness and lighting are incredible. Very nice job.', '2005-05-15 22:45:29.000000', NULL, 1),
(1387372, 175601, 22734, '<td valign="top">Wow, what a better use for a guitar case. This image is super. Bumping up.</td>', 'Wow, what a better use for a guitar case. This image is super. Bumping up.', '2005-05-15 22:45:36.000000', NULL, 1),
(1387373, 175558, 33817, '<td valign="top">Clean, crisp and simple.  Nice work!   And just in case you get a comment or two about the highlights -- I like them just as they are.  One opinion among the many -- and certainly worth what you paid for it  ;o)</td>', 'Clean, crisp and simple.  Nice work!   And just in case you get a comment or two about the highlights -- I like them just as they are.  One opinion among the many -- and certainly worth what you paid for it  ;o)', '2005-05-15 22:45:56.000000', NULL, 1),
(1387375, 175259, 33947, '<td valign="top">Creative, and the sharpness, lighting and reflections are very nice.</td>', 'Creative, and the sharpness, lighting and reflections are very nice.', '2005-05-15 22:46:39.000000', NULL, 1),
(1387376, 175756, 30392, '<td valign="top">A bit of a stretch but I like it, nice vanishing point towards the dark gloomy mountains</td>', 'A bit of a stretch but I like it, nice vanishing point towards the dark gloomy mountains', '2005-05-15 22:49:28.000000', NULL, 1),
(1387384, 175490, 22734, '<td valign="top">Very nice composition. Bump.</td>', 'Very nice composition. Bump.', '2005-05-15 22:53:20.000000', NULL, 1),
(1387385, 175385, 22734, '<td valign="top">Impressive. Bump.</td>', 'Impressive. Bump.', '2005-05-15 22:54:32.000000', NULL, 1),
(1387387, 175603, 33947, '<td valign="top">Beautiful light on the flower. Nice bee capture. Sharp.</td>', 'Beautiful light on the flower. Nice bee capture. Sharp.', '2005-05-15 22:55:36.000000', NULL, 1),
(1387388, 175574, 22734, '<td valign="top">Quite a colorful and wet and slippery look. Bumping up on fastastic colors.</td>', 'Quite a colorful and wet and slippery look. Bumping up on fastastic colors.', '2005-05-15 22:55:45.000000', NULL, 1),
(1387390, 175793, 22734, '<td valign="top">A great image with that overall appeal of outstanding composition and composite. Memorable. Here is another bump for great job.</td>', 'A great image with that overall appeal of outstanding composition and composite. Memorable. Here is another bump for great job.', '2005-05-15 22:56:36.000000', NULL, 1),
(1387391, 175613, 22734, '<td valign="top">Great image with good depth. Bumping up.</td>', 'Great image with good depth. Bumping up.', '2005-05-15 22:58:52.000000', NULL, 1),
(1387393, 175478, 33947, '<td valign="top">In this instance I think I might have preferred seeing the cage, but, I do still think this meets the challenge, and the clarity and lighting are very nice. Great eyes.</td>', 'In this instance I think I might have preferred seeing the cage, but, I do still think this meets the challenge, and the clarity and lighting are very nice. Great eyes.', '2005-05-15 23:03:35.000000', NULL, 1),
(1387395, 174797, 33947, '<td valign="top">Great expression, and interesting texture with the screen.</td>', 'Great expression, and interesting texture with the screen.', '2005-05-15 23:04:39.000000', NULL, 1),
(1387396, 175558, 33947, '<td valign="top">Wow, the clarity and reflective quality of this shot is fanstastic.</td>', 'Wow, the clarity and reflective quality of this shot is fanstastic.', '2005-05-15 23:05:52.000000', NULL, 1),
(1387397, 175736, 33947, '<td valign="top">You made me smile. Very creative way to meet the challenge. Good lighting and contrast.</td>', 'You made me smile. Very creative way to meet the challenge. Good lighting and contrast.', '2005-05-15 23:06:55.000000', NULL, 1),
(1387398, 175265, 33947, '<td valign="top">Great shot! I love the repetition of the squares in the opposite corners, and I like the soft taupes throughout.</td>', 'Great shot! I love the repetition of the squares in the opposite corners, and I like the soft taupes throughout.', '2005-05-15 23:08:53.000000', NULL, 1),
(1387404, 174604, 33947, '<td valign="top">You made me smile. Interesting take on the challenge, and nice lighting.</td>', 'You made me smile. Interesting take on the challenge, and nice lighting.', '2005-05-15 23:14:13.000000', NULL, 1),
(1387411, 175385, 33947, '<td valign="top">I really like the lighting, the highlights in their eyes, and the sharpness.</td>', 'I really like the lighting, the highlights in their eyes, and the sharpness.', '2005-05-15 23:18:30.000000', NULL, 1),
(1387414, 174941, 33947, '<td valign="top">Fun picture. Sharp. Like Pooh''s reflection.</td>', 'Fun picture. Sharp. Like Pooh''s reflection.', '2005-05-15 23:20:10.000000', NULL, 1),
(1387416, 175210, 33947, '<td valign="top">Very nice skin tones, and the eyes are great. Nice highlights thorughout. SHARP!!</td>', 'Very nice skin tones, and the eyes are great. Nice highlights thorughout. SHARP!!', '2005-05-15 23:21:19.000000', NULL, 1),
(1387419, 173135, 32997, '<td valign="top">Great shot..love the contrast between the cat and the red..and how the colour supports the anger/tension..framing the white cat with the other too is just plain brilliant too!</td>', 'Great shot..love the contrast between the cat and the red..and how the colour supports the anger/tension..framing the white cat with the other too is just plain brilliant too!', '2005-05-15 23:28:08.000000', NULL, 1),
(1387421, 175640, 32997, '<td valign="top">I love how you have them looking at you..solid shot.</td>', 'I love how you have them looking at you..solid shot.', '2005-05-15 23:29:26.000000', NULL, 1),
(1387429, 175101, 32997, '<td valign="top">Fascinating...this is very hypnotic..well done!</td>', 'Fascinating...this is very hypnotic..well done!', '2005-05-15 23:33:17.000000', NULL, 1),
(1387432, 175533, 32997, '<td valign="top">i was staring at this for awhile..kind of forgot what I was doing..well done!</td>', 'i was staring at this for awhile..kind of forgot what I was doing..well done!', '2005-05-15 23:35:29.000000', NULL, 1),
(1387471, 175475, 6668, '<td valign="top">Beautiful! Excellent lighting, nicely done! 10</td>', 'Beautiful! Excellent lighting, nicely done! 10', '2005-05-16 00:00:42.000000', NULL, 1),
