INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1393767, 175793, 12253, '<td valign="top">Very creative!  Another amazing work of creative energy and talent.  I can''t believe you made such huge printouts when you could have simply shrunk your mother down.  And tell your mother she looks young enough to be your sister.</td>', 'Very creative!  Another amazing work of creative energy and talent.  I can''t believe you made such huge printouts when you could have simply shrunk your mother down.  And tell your mother she looks young enough to be your sister.', '2005-05-18 03:21:51.000000', NULL, 0),
(1394790, 174289, 22748, '<td valign="top">I think this is the single most underrated image in the challenge. A very striking image. I love how the eye is illuminated, the lighting is fabulous.</td>', 'I think this is the single most underrated image in the challenge. A very striking image. I love how the eye is illuminated, the lighting is fabulous.', '2005-05-18 12:22:34.000000', NULL, 0),
(1395406, 174736, 12962, '<td valign="top">Congratulations on your top twenty.  This evokes of something in the past ...</td>', 'Congratulations on your top twenty.  This evokes of something in the past ...', '2005-05-18 15:27:44.000000', NULL, 0),
(1395793, 175614, 16241, '<td valign="top">this is great!</td>', 'this is great!', '2005-05-18 17:38:11.000000', NULL, 0),
(1396449, 175525, 20462, '<td valign="top">Thanks for all the comments and added favorites.  To respond to a few comments and points:<br/> <br/>1.  I am still trying to find a style.  I tend to like these romanticized portions of life where light and nostalgia blend together.  I find opposites really work together.  Young model/Old Looking Fence.  Sharp Subject/Blurred Background.  Lambency/Shadow.  Design/Coincidence.<br/> <br/>2.  Many people felt it was neat imaged.  I don''t have neat image and am still debating on purchasing it.  Hmmm, close call still, especially if I can achieve a glossed smooth looks without it.<br/> <br/>3.  I think the ultimate "trick" to photography and art, is to shape the viewer''s eye and mind to "see" what you see.  And to make that eye go to exactly where you want it to go is talent in its purest form.  That is what leading lines, composition and all these technical nuances are really trying to do.  I am not saying this picture achieves that, but that is my focus right now.  <br/> <br/>Thanks again.</td>', 'Thanks for all the comments and added favorites.  To respond to a few comments and points: 1.  I am still trying to find a style.  I tend to like these romanticized portions of life where light and nostalgia blend together.  I find opposites really work together.  Young model/Old Looking Fence.  Sharp Subject/Blurred Background.  Lambency/Shadow.  Design/Coincidence. 2.  Many people felt it was neat imaged.  I don''t have neat image and am still debating on purchasing it.  Hmmm, close call still, especially if I can achieve a glossed smooth looks without it. 3.  I think the ultimate "trick" to photography and art, is to shape the viewer''s eye and mind to "see" what you see.  And to make that eye go to exactly where you want it to go is talent in its purest form.  That is what leading lines, composition and all these technical nuances are really trying to do.  I am not saying this picture achieves that, but that is my focus right now.   Thanks again.', '2005-05-18 20:54:16.000000', NULL, 0),
(1396883, 175751, 1717, '<td valign="top">freaky!  and very cool! :)<br/> <br/>looking at it again, it reminds me of photos i''ve seen of the exhibits in the Mütter Museum in Philadelphia.  really a great shot, jason!<br/><br/><i>Message edited by author 2005-05-18 22:12:36.</i></td>', 'freaky!  and very cool! :) looking at it again, it reminds me of photos i''ve seen of the exhibits in the Mütter Museum in Philadelphia.  really a great shot, jason!', '2005-05-18 23:10:13.000000', '2005-05-18 23:12:36.000000', 0),
(1397143, 175666, 28710, '<td valign="top">The first thing I noticed about the selective desat was the the "bleeding" of the B&amp;W into the color area. Another poster mentioned that it was a bit messy. Another mentioned that it was very Wizard of OZ.<br/> <br/>Personally, I like it. I feel that it gives a more magical ambiance. Like an aura boiling and spinning around the edges of the physical objects on the edge of reality. I''m no expert, but that''s what it feels like when I look at it. I don''t think that I would feel the same if the color rolled into the stonework, or if the blur was very uniform. <br/> <br/>It may or may not be intentional, but I think it works perfectly.</td>', 'The first thing I noticed about the selective desat was the the "bleeding" of the B&W into the color area. Another poster mentioned that it was a bit messy. Another mentioned that it was very Wizard of OZ. Personally, I like it. I feel that it gives a more magical ambiance. Like an aura boiling and spinning around the edges of the physical objects on the edge of reality. I''m no expert, but that''s what it feels like when I look at it. I don''t think that I would feel the same if the color rolled into the stonework, or if the blur was very uniform.  It may or may not be intentional, but I think it works perfectly.', '2005-05-19 00:50:23.000000', NULL, 0),
(1397736, 175666, 6870, '<td valign="top">Fun and evocative image, Bob! I love it. Congratulations on another ribbon!</td>', 'Fun and evocative image, Bob! I love it. Congratulations on another ribbon!', '2005-05-19 10:01:01.000000', NULL, 0),
